import React from 'react';
import { Container, List, Title, Item } from './styles'; // Importando os estilos
import Pratos from '../../models/Pratos'; // Importando a classe 'Pratos' corretamente


// Definindo a tipagem das props
interface ProductsListProps {
  title: string;
  pratos: Pratos[];
  size: 'grande' | 'pequeno';
  background: string;
}

const ProductsList: React.FC<ProductsListProps> = ({ title, pratos, size }) => {
  return (
    <Container>
      <div>
        <Title>{title}</Title>
        <List size={size}>
          {pratos.map((prato) => (
            <Item key={prato.id} size={size}>
              <img src={prato.image} alt={prato.title} />
              <h3>{prato.title}</h3>
              <p>{prato.description}</p>
            </Item>
          ))}
        </List>
      </div>
    </Container>
  );
};

export default ProductsList;
